URL_IDS = {s['url']:s['id'] for s in OLD_SOURCES}
# Retain the source IDs used in the independently reviewed authoring snapshot,
# even after the integrator registers aliases for the same official URL.
URL_IDS.update({'https://www.imec-int.com/en/what-we-offer/development/photonics': 'a-imec-photonics', 'https://www.intel.com/content/www/us/en/newsroom/news/intel-unveils-first-integrated-optical-io-chiplet.html': 'intel-photonics', 'https://3dfabric.tsmc.com/english/dedicatedFoundry/technology/cowos.htm': 'pkb-tsmc-cowos', 'https://3dfabric.tsmc.com/english/dedicatedFoundry/technology/SoIC.htm': 'pkb-tsmc-soic', 'https://www.aimphotonics.com/pdk': 'v4-related-2344851e16c4', 'https://www.aimphotonics.com/news/aim-photonics-introduces-assembly-design-kit-to-streamline-photonic-packaging-design': 'v9ct-adk', 'https://biblio.ugent.be/publication/8172290': 'v9ct-coherent', 'https://www.oiforum.com/wp-content/uploads/OIF-Co-Packaging-3.2T-Module-01.0.pdf': 'v9ct-cpo', 'https://www.oiforum.com/wp-content/uploads/OIF-ELSFP-02.0.pdf': 'v9ct-elsfp', 'https://webstore.iec.ch/en/publication/65836': 'v9ct-emc', 'https://webstore.iec.ch/en/publication/3587': 'v9ct-iec', 'https://www.intel.com/content/www/us/en/foundry/packaging.html': 'v9ct-intel', 'https://www.nature.com/articles/s41467-017-00714-1': 'v9ct-mesh', 'https://www.nature.com/articles/s41598-023-46819-0': 'v9ct-photoelastic', 'https://www.aimphotonics.com/tap': 'v9ct-tap', 'https://optics.ansys.com/hc/en-us/articles/360042338014-Thermally-tuned-waveguide-FEEM': 'v9ct-thermal', 'https://optics.ansys.com/hc/en-us/articles/47617107334291-Modeling-thermal-crosstalk-in-photonic-circuit-simulation-with-INTERCONNECT': 'v9ct-thermalmatrix'})
SOURCES=[]; SR={}; COURSES=[]; PLACES=[]; RELATED=[]
def bi(s):
    a=s.split('~'); assert len(a)==2, s; return a
def source(key,title,publisher,url,scope):
    sid=URL_IDS.get(url,'v9ct-'+key); SR[key]=sid
    if url not in URL_IDS or sid.startswith('v9ct-'):
        t,te=bi(title); sc,sce=bi(scope)
        SOURCES.append(dict(id=sid,title=t,titleEn=te,publisher=publisher,url=url,scope=sc,scopeEn=sce,category='packaging',sourceType='primary',accessedAt='2026-10-14',imageReuse='link-only',imageReuseEn='Link only; no source illustration reproduced.'))
        URL_IDS[url]=sid
