def course(cid,focus,stage_names,rows,example,model,limits,myths,sources,related,subcategory='photonic-systems',place=None):
    """Rows: bilingual unit title | mechanism | discriminating evidence."""
    f,fe=bi(focus); ex,exe=bi(example); mo,moe=bi(model); lim,lime=bi(limits)
    myths=[bi(x) for x in myths]; assert len(myths)>=3
    rows=[r.split('|') for r in rows.strip().splitlines() if r.strip()]
    assert len(rows)==12,(cid,len(rows)); assert all(len(r)==3 for r in rows),(cid,rows)
    src=[SR[s] for s in sources]; c=dict(CAT[cid]); [c.pop(k,None) for k in ['photoId','subcategoryTitle','subcategoryTitleEn']]; c['kind']='project' if int(cid[1:])>=196 else 'craft'; c.update(status='guided',contentStatus='reviewable-educational-curriculum',curriculumVersion=9,depth=4,stepCount=24,estimatedMinutes=840,simulationOnly=True,languageCoverage=['zh-TW','en'],sourceIds=src,subcategory=subcategory)
    c['summary']=f'從{f}拆成 4 階段、24 項可保存的工程作業；包含物理模型、算例、可區分失效的量測與驗收證據。'
    c['summaryEn']=f'Four stages and 24 saveable work packages investigate {fe}, including physical models, a worked example, discriminating measurements and acceptance evidence.'
    c['scope']='公開原理的概念設計與資料判讀課，非供應商配方或可直接投產的操作程序。算例全部是教學假設；真正驗收須使用適用版本、合格設備與實測參數。代表照片、示意圖與影片不宣稱為每步製造實拍。'
    c['scopeEn']='Conceptual design and data interpretation from public principles, not a vendor recipe or production-ready procedure. All worked inputs are educational assumptions. Real acceptance requires the applicable revision, qualified equipment and measured parameters. Representative media are not claimed as footage of every operation.'
    c['workedExample']={'title':'可重算的教學算例','titleEn':'Reproducible teaching example','text':ex,'textEn':exe,'assumptions':lim,'assumptionsEn':lime,'sourceScope':'自行編寫的假想算例；原始資料支援領域原理，不提供這組假設數值。','sourceScopeEn':'Independently authored hypothetical exercise; primary sources support the field, not these chosen inputs.'}
    stages=[bi(x) for x in stage_names.split('|')]; assert len(stages)==4
    c['diagram']={'type':'photonics','labels':[s[0] for s in stages],'labelsEn':[s[1] for s in stages],'original':True,'notToScale':True}
    c['stages']=[]
    for k,(st,ste) in enumerate(stages):
        stage={'id':f'{cid}-stage{k+1:02d}','order':k+1,'title':st,'titleEn':ste,'description':f'以三個技術單元完成「{st}」的模型與驗證，六項作業各自留存交付物。','descriptionEn':f'Three technical units address {ste} through six separately saved modeling and verification work packages.','steps':[]}
        for j in range(3):
            unit=k*3+j; title,principle,evidence=map(bi,rows[unit]); p,pe=principle; ev,eve=evidence
            for mode in range(2):
                n=unit*2+mode+1; sid=f'{cid}-v9-{n:02d}'
                suffix=['模型與設計','量測與判別'][mode]; suffixen=['model and design','measurement and diagnosis'][mode]
                wrong=myths[(unit+mode)%len(myths)]; wrong2=myths[(unit+mode+1)%len(myths)]
                instruction=(f'先以師傅示意確認「{title[0]}」的輸入、輸出與座標，再在學徒工作台完成對應元件或資料流的排列。{p} 用本單元的變數畫出至少兩種設計狀態，說明它們在「{ev}」的驗證中應有何差異；把待量測參數另列，不以動畫位置當成實際公差。' if mode==0 else f'保留上一作業的模型，現在檢驗它是否足以解釋觀察。{ev} 記錄原始量、單位、基準與重複量測差異；以支持及否定各一項證據比較「{p}」與錯誤假說「{wrong[0]}」，最後提出放行、重測或修模決定。')
                instructionen=(f'Use the mentor view to identify the inputs, outputs and coordinates for {title[1].lower()}, then arrange the corresponding components or data flow in the apprentice workspace. {pe} Draw at least two design states using this unit\'s variables and predict how the following verification distinguishes them: {eve} List unmeasured parameters separately; animation positions are not manufacturing tolerances.' if mode==0 else f'Retain the previous model and test whether it explains the observations. {eve} Record raw quantities, units, reference conditions and repeatability. Use supporting and falsifying evidence to compare "{pe}" against the incorrect hypothesis "{wrong[1]}"; decide whether to accept, repeat or revise the model.')
                if unit==2:
                    instruction+=' '+ex; instructionen+=' '+exe
                correct=principle if mode==0 else evidence
                options=[correct,wrong,wrong2]; shift=(n-1)%3; options=options[-shift:]+options[:-shift] if shift else options
                step=dict(id=sid,order=n,sequence=n,estimatedMinutes=35,simulationOnly=True,sourceIds=src,prerequisiteIds=[f'{cid}-v9-{n-1:02d}'] if n>1 else [],title=f'{title[0]}：{suffix}',titleEn=f'{title[1]}: {suffixen}',objective=f'以「{title[0]}」' + ('建立可檢驗的物理模型' if mode==0 else '區分機制並作出有證據的驗收決定') + '，交付可重算且列明邊界的工程紀錄。',objectiveEn=('Build a falsifiable physical model' if mode==0 else 'Discriminate mechanisms and make an evidence-based acceptance decision') + f' for {title[1].lower()}, with reproducible calculations and stated boundaries.',instruction=instruction,instructionEn=instructionen,observation=ev,observationEn=eve,failure=f'須排除的錯誤假說：{wrong[0]} 若觀察不支持預測，先核對基準與單位，再依本步判別量測定位原因；不能只調參到曲線相合。',failureEn=f'Incorrect hypothesis to reject: {wrong[1]} If observations disagree, first check references and units, then use this step\'s discriminating measurement; do not simply tune parameters until curves agree.',check=(f'提交{title[0]}的兩狀態模型、變數表，以及能由「{ev}」反駁模型的預測。' if mode==0 else f'提交{title[0]}的量測判別表：{ev} 附上基準、重複性或不確定度，及不能由本資料判定的結論。'),checkEn=(f'Submit two model states and a variable table for {title[1].lower()}, plus a falsifiable prediction using: {eve}' if mode==0 else f'Submit a measurement-discrimination table for {title[1].lower()}: {eve} Include the reference, repeatability or uncertainty, and conclusions the data cannot support.'),knowledge=[{'id':sid+'-k1','title':'本單元物理機制','titleEn':'Unit mechanism','text':p,'textEn':pe,'sourceIds':src},{'id':sid+'-k2','title':'獨立驗證與證據','titleEn':'Independent verification and evidence','text':ev,'textEn':eve,'sourceIds':src},{'id':sid+'-k3','title':'量化模型與適用邊界','titleEn':'Quantitative model and validity boundary','text':mo+' '+lim,'textEn':moe+' '+lime,'sourceIds':src}],quiz={'question':f'要審查「{title[0]}」，哪項主張或驗證方法有根據？','questionEn':f'Which claim or verification is justified when reviewing {title[1].lower()}?','options':[o[0] for o in options],'optionsEn':[o[1] for o in options],'answer':shift,'explanation':p+' '+ev,'explanationEn':pe+' '+eve})
                stage['steps'].append(step)
        c['stages'].append(stage)
    COURSES.append(c)
    refs=[{key:REFS[s][key] for key in ['title','titleEn','publisher','url'] if key in REFS[s]} for s in src]
    pl=dict(place or BASEPLACE)
    pl['coordinateScope']='公開機構的近似代表點；是研究／測試／供應鏈學習定位，不表示本課全部製程在此量產，也不是設備位置。'
    pl['coordinateScopeEn']='Approximate public institutional reference for research, testing or supply-chain learning; not a claim that every course process is produced here or an equipment location.'
    PLACES.append(dict(courseId=cid,place=pl,summary=f'{c["title"]}以{f}連結元件物理與系統驗證。此代表地點用於認識研究與封裝供應鏈；課程由多個公開來源交叉編寫。',summaryEn=f'{c["titleEn"]} links device physics and system validation through {fe}. This representative location illustrates the research and packaging ecosystem; the curriculum draws on several public sources.',connection=f'以{f}比較相關工法；重新核對材料、波段、控制拓撲與驗收門檻。',connectionEn=f'Compare related methods through {fe}, rechecking materials, wavelength, control topology and acceptance limits.',history=[{'year':'研究脈絡 / Research context','title':'從單元件指標到可測試系統','titleEn':'From component metrics to testable systems','text':f'本課把{f}放在材料、介面及封裝的連續證據鏈中。下列原始研究與機構資料呈現不同發展路線；此欄是教學脈絡，並非宣稱此地的發明年表。','textEn':f'This course puts {fe} within a continuous evidence chain of materials, interfaces and packaging. The primary studies and institutional records show different development routes; this is learning context, not a claimed invention timeline for this location.','sourceIds':src}],references=refs,sourceIds=src))
    rels=[]
    for rid,transfer,difference,practice in related:
        tr,tre=bi(transfer); diff,diffe=bi(difference); pr,pre=bi(practice)
        assert rid in CAT and rid!=cid
        rels.append(dict(id=rid,title=CAT[rid]['title'],titleEn=CAT[rid]['titleEn'],why=tr,whyEn=tre,transfer=tr,transferEn=tre,difference=diff,differenceEn=diffe,practice=[pr,'在兩課中各選一個能推翻結論的量測。','標出交接時不能直接沿用的材料參數或控制條件。'],practiceEn=[pre,'Choose one falsifying measurement in each course.','Identify material parameters or control conditions that cannot be transferred unchanged.'],referenceUrls=[r['url'] for r in refs]))
    assert len(rels)==2
    RELATED.append(dict(courseId=cid,overview=f'由{f}延伸到不同工法，保留物理關係並重新界定系統邊界。',overviewEn=f'Extend {fe} to related methods while retaining physical relationships and redefining system boundaries.',related=rels,references=refs))

source('photoelastic','1550 nm 矽光彈係數的溫度依賴~Temperature-dependent photo-elastic coefficient of silicon at 1550 nm','Dickmann et al. / Scientific Reports','https://www.nature.com/articles/s41598-023-46819-0','原始量測指出晶向與溫度依賴；本課不把塊材係數直接當成導波模態係數。~Original measurements establish orientation and temperature dependence; bulk coefficients are not directly equated to guided-mode coefficients.')
source('thermalmatrix','光子電路熱串擾矩陣建模~Thermal-crosstalk matrix modeling for photonic circuits','Ansys Optics','https://optics.ansys.com/hc/en-us/articles/47617107334291-Modeling-thermal-crosstalk-in-photonic-circuit-simulation-with-INTERCONNECT','熱功率到元件溫升的模型流程。~Model workflow from heater powers to device temperatures.')
source('oci','2024 光學 I/O 小晶片展示~2024 optical I/O chiplet demonstration','Intel','https://www.intel.com/content/www/us/en/newsroom/news/intel-unveils-first-integrated-optical-io-chiplet.html','供應商展示及明確年份；課程預算是獨立假想設計。~Dated supplier demonstration; course budgets are independently chosen hypothetical designs.')
source('iec','IEC 60825-1:2014 公開標準目錄~IEC 60825-1:2014 public standard catalog','IEC','https://webstore.iec.ch/en/publication/3587','目錄只確認分類與要求的適用範圍；沒有重製付費標準或自行指定安全限值。~The catalog identifies classification/requirements scope; no paid standard text is reproduced and no safety limits are invented.')
source('emc','CISPR 32:2015+A1:2019 公開標準目錄~CISPR 32:2015+A1:2019 public standard catalog','IEC','https://webstore.iec.ch/en/publication/65836','多媒體設備發射測試的範圍；實際適用性、等級與限值由合格實驗室及適用法規確定。~Scope of multimedia-equipment emissions tests; applicability, class and limits require the applicable rules and qualified laboratory.')
