# Normalize a handful of authored Chinese variants; leave technical expressions intact.
def normalized(obj):
 if isinstance(obj,str):
  for a,b in {'独立':'獨立','验证':'驗證','据此':'據此','頻譜与':'頻譜與'}.items():obj=obj.replace(a,b)
  return obj
 if isinstance(obj,list):return [normalized(x) for x in obj]
 if isinstance(obj,dict):return {k:normalized(v) for k,v in obj.items()}
 return obj
used={sid for c in COURSES for sid in c['sourceIds']}|{sid for p in PLACES for sid in p['sourceIds']}
output=normalized(dict(courses=COURSES,sources=[s for s in SOURCES if s['id'] in used],places=PLACES,related=RELATED))
assert len(COURSES)==16 and {c['id'] for c in COURSES}=={f'a{i}' for i in range(185,201)}
assert len(PLACES)==len(RELATED)==16
